# ------------------------------------ UE pool related ------------------------------------
class RequiredUeNotFound(RequiredDeviceNotFound):
    """Required Ue Not Found"""

    def __str__(self):
        return f'Cannot find Ue that matches requirements: {str(self.device_characteristics)}'


class NotEnoughRequiredUes(RequiredDeviceNotFound):
    """Insufficient number of UEs compatible with 'Required Ue specification'"""

    def __init__(self, required_ue_number, current_ue_number, device_characteristics):
        """
        Basic initialization.

        :param required_ue_number: number of UEs that user wants to get
        :param current_ue_number: current UE wich lib tries to get
        """
        super().__init__(device_characteristics)
        self.required_ue_number = required_ue_number
        self.current_ue_number = current_ue_number

    def __str__(self):
        err = f"Requested {self.required_ue_number} UEs that match requirements {self.device_characteristics}"
        err += f", found only {self.current_ue_number} such UEs"
        return err


class UnknownUe(UnknownDevice):
    """Unknown Ue"""
    pass


class UnknownUeGroup(UnknownDevice):
    """Unknown Ue group"""
    pass


class UnknownUePoolPackage(UnknownDevicePoolPackage):
    """Unknown Ue Pool Package"""

    def __str__(self):
        err = f"Can't determine package for {self.module_name_of_pool}.{self.class_name_of_pool}"
        err += "\n  expected format of pool-type: <prefix>Ue<suffix>"
        err += "\n  example: SomeUePool (maps to ute_ue.ue.some.someuepool.SomeUePool)"
        return err


