class OutOfOrderError(AbstractUeLibException):
    """Out Of Order Error"""

    def __init__(self, msg_name, message_flow):
        """
        Basic initialization.
        :param msg_name:
        :param message_flow:
        """
        super().__init__()
        # TODO put message name in Message object
        self.msg_name = msg_name
        self.message_flow = message_flow

    def __str__(self):
        err = f"Message {str(self.msg_name)} out of order"
        return err


